WITH sorted_users AS ( SELECT ID FROM SYS_USER WHERE TENANT_ID = #{tid} AND () ORDER BY UTC_MODIFY DESC
LIMIT 18446744073709551615 OFFSET #{count}
OFFSET #{count} ROWS
) UPDATE SYS_USER u SET FROZEN = #{frz} FROM sorted_users s WHERE u.ID = s.ID AND (u.FROZEN IS NULL OR u.FROZEN != 1) AND ()

UPDATE SYS_USER u SET frozen = 1 FROM SYS_TENANT t WHERE u.tenant_id = t.id AND t.frozen = 1 AND u.tenant_id IN
#{id}
AND ()

WITH ordered_users AS ( SELECT u.id, u.tenant_id, u.frozen, t.auth_user_count, ROW_NUMBER() OVER (PARTITION BY u.tenant_id ORDER BY u.utc_create ASC) AS rn FROM sys_user u JOIN sys_tenant t ON u.tenant_id = t.id WHERE u.tenant_id IN
#{id}
AND () ) UPDATE sys_user u SET frozen = 0 FROM ordered_users o WHERE u.id = o.id AND o.rn <= o.auth_user_count AND u.frozen != -1 AND u.frozen != 0 AND ()
